import React from 'react';
import type { Meta, StoryObj } from "@storybook/nextjs";
import { Button, Box, Flex, Text } from "../index";
import { TooltipComponent } from "./Tooltip";

const meta: Meta<typeof TooltipComponent> = {
  title: "Design System/Atoms/Tooltip",
  component: TooltipComponent,
  parameters: {
    docs: {
      description: {
        component: `A tooltip component for displaying contextual information on hover or click. Built on Radix UI Tooltip primitive with smooth animations and automatic collision detection.

**Accessibility:**
- Keyboard navigation: Tooltips appear when the trigger receives keyboard focus
- Screen readers: Content is announced to screen reader users
- ESC key: Closes tooltip when focused
- Best practice: Use tooltips for supplementary information, not critical content that users must read

**When to use:**
- Short descriptions (1-2 sentences)
- Additional context for UI elements
- Explaining abbreviations or technical terms

**When NOT to use:**
- Critical information users must see
- Long content (use a Dialog or Popover instead)
- Interactive content (tooltips dismiss on interaction)`,
      },
    },
  },
  argTypes: {
    content: {
      control: 'text',
      description: 'Tooltip content to display',
      table: {
        type: { summary: 'React.ReactNode | string' },
      },
    },
    side: {
      control: { type: 'select' },
      options: ['top', 'bottom', 'left', 'right'],
      description: 'Preferred side of the trigger to render the tooltip',
      table: {
        type: { summary: '"top" | "bottom" | "left" | "right"' },
        defaultValue: { summary: 'bottom' },
      },
    },
    sideOffset: {
      control: { type: 'number', min: 0, max: 50, step: 1 },
      description: 'Distance in pixels from the trigger',
      table: {
        type: { summary: 'number' },
        defaultValue: { summary: '5' },
      },
    },
    showOnClick: {
      control: 'boolean',
      description: 'Show tooltip on click instead of hover (useful for mobile)',
      table: {
        type: { summary: 'boolean' },
        defaultValue: { summary: 'false' },
      },
    },
    showArrow: {
      control: 'boolean',
      description: 'Display arrow pointing to trigger element',
      table: {
        type: { summary: 'boolean' },
        defaultValue: { summary: 'true' },
      },
    },
    avoidCollisions: {
      control: 'boolean',
      description: 'Automatically adjust position to avoid viewport edges',
      table: {
        type: { summary: 'boolean' },
        defaultValue: { summary: 'true' },
      },
    },
    delayDuration: {
      control: { type: 'number', min: 0, max: 2000, step: 100 },
      description: 'Delay in milliseconds before showing tooltip',
      table: {
        type: { summary: 'number' },
        defaultValue: { summary: '0' },
      },
    },
  },
};

export default meta;
type Story = StoryObj<typeof TooltipComponent>;

